Recall that an increasing subsequence is a sequence of integers such that each number is larger than the previous.

def longest_increasing_subsequence(nums):
    """Return the length of the longest increasing subsequence in O(n log n) time."""
    # Sort the input list in non-decreasing order
    sorted_nums = sorted(nums)

    # Initialize a list to store the lengths of the increasing subsequences
    lengths = [1] * len(sorted_nums)

    # Iterate over the sorted list and update the lengths of the increasing subsequences
    for i in range(1, len(sorted_nums)):
        for j in range(i):
            if sorted_nums[i] > sorted_nums[j]:
                lengths[i] = max(lengths[i], lengths[j] + 1)

    # Return the maximum length of an increasing subsequence
    return max(lengths)

