Solution: Debouncing is a technique used to prevent multiple calls to a function within a given time interval. In this case, we want to call the function only after the user has stopped typing for 300ms. Here's an example implementation:

    function debounce(func, wait) {
      let timeout;

      return function() {
        const context = this;
        const args = arguments;

        clearTimeout(timeout);
        timeout = setTimeout(() => {
          func.apply(context, args);
        }, wait);
      };
    }

    // Example usage:
    const input = document.querySelector('input');
    const handler = debounce((event) => {
      console.log(`Input value: ${event.target.value}`);
    }, 300);

    input.addEventListener('input', handler);

